const now = new Date();
const pastDate = new Date();
pastDate.setDate(now.getDate() - 7);

const startDate = pastDate.toISOString().split('T')[0];
const endDate = now.toISOString().split('T')[0];

return [{
  json: {
    startDate,
    endDate,
    owner: 'andbelP',
    repo: 'test-pr-review'
  }
}];

const dateInfo = $('Calculate Date Range').first().json;
const createdIssuesData = $('GitHub API: Created Issues').first().json || {};
const closedIssuesData = $('GitHub API: Closed Issues').first().json || {};
const createdPRsData = $('GitHub API: Created PRs').first().json || {};
const mergedPRsData = $('GitHub API: Merged PRs').first().json || {};

const createdItems = createdIssuesData.items || [];
const closedItems = closedIssuesData.items || [];
const prItems = createdPRsData.items || [];
const mergedItems = mergedPRsData.items || [];

const totalCreatedIssues = createdIssuesData.total_count !== undefined ? createdIssuesData.total_count : createdItems.length;
const totalClosedIssues = closedIssuesData.total_count !== undefined ? closedIssuesData.total_count : closedItems.length;
const totalCreatedPRs = createdPRsData.total_count !== undefined ? createdPRsData.total_count : prItems.length;
const totalMergedPRs = mergedPRsData.total_count !== undefined ? mergedPRsData.total_count : mergedItems.length;

// 1. Grouping by Type
const typeCounts = {
  bug: 0,
  task: 0,
  feature: 0,
  'needs-triage': 0,
  other: 0
};

for (const item of createdItems) {
  const labels = (item.labels || []).map(l => (typeof l === 'string' ? l : l.name || '').toLowerCase());
  let matched = false;
  if (labels.includes('bug')) { typeCounts.bug++; matched = true; }
  if (labels.includes('task')) { typeCounts.task++; matched = true; }
  if (labels.includes('feature')) { typeCounts.feature++; matched = true; }
  if (labels.includes('needs-triage')) { typeCounts['needs-triage']++; matched = true; }
  if (!matched) {
    typeCounts.other++;
  }
}

// 2. Grouping by Author
const authorCounts = {};
for (const item of createdItems) {
  const author = (item.user && item.user.login) ? item.user.login : 'anonymous';
  authorCounts[author] = (authorCounts[author] || 0) + 1;
}
const sortedAuthors = Object.entries(authorCounts).sort((a, b) => b[1] - a[1]);

// 3. Read previous week from Data Table
let prev = {
  week_date: '2026-11-09',
  created_issues: 2,
  closed_issues: 1,
  created_prs: 4,
  merged_prs: 1,
  bugs: 1,
  tasks: 1,
  features: 0,
  needs_triage: 0
};

try {
  const prevRows = $('Read Previous Week (Data Table)').all().map(i => i.json);
  if (prevRows && prevRows.length > 0) {
    // take the last recorded week
    const lastRow = prevRows[prevRows.length - 1];
    prev = {
      week_date: lastRow.week_date || prev.week_date,
      created_issues: Number(lastRow.created_issues !== undefined ? lastRow.created_issues : prev.created_issues),
      closed_issues: Number(lastRow.closed_issues !== undefined ? lastRow.closed_issues : prev.closed_issues),
      created_prs: Number(lastRow.created_prs !== undefined ? lastRow.created_prs : prev.created_prs),
      merged_prs: Number(lastRow.merged_prs !== undefined ? lastRow.merged_prs : prev.merged_prs),
      bugs: Number(lastRow.bugs !== undefined ? lastRow.bugs : prev.bugs),
      tasks: Number(lastRow.tasks !== undefined ? lastRow.tasks : prev.tasks),
      features: Number(lastRow.features !== undefined ? lastRow.features : prev.features),
      needs_triage: Number(lastRow.needs_triage !== undefined ? lastRow.needs_triage : prev.needs_triage)
    };
  }
} catch (e) {
  // fallback to baseline
}

// 4. Calculate Deltas
const deltaIssues = totalCreatedIssues - prev.created_issues;
const deltaClosed = totalClosedIssues - prev.closed_issues;
const deltaPRs = totalCreatedPRs - prev.created_prs;
const deltaMerged = totalMergedPRs - prev.merged_prs;

const deltaBugs = typeCounts.bug - prev.bugs;
const deltaTasks = typeCounts.task - prev.tasks;
const deltaFeatures = typeCounts.feature - prev.features;
const deltaTriage = typeCounts['needs-triage'] - prev.needs_triage;

const formatDelta = (d) => {
  if (d > 0) return `+${d}`;
  if (d < 0) return `${d}`;
  return '0';
};

// 5. Prompt for LLM
const promptData = `
Отчётный период: ${dateInfo.startDate} — ${dateInfo.endDate}
Статистика текущей недели (в скобках разница к прошлой неделе от ${prev.week_date}):
- Новые Issues: ${totalCreatedIssues} (прошлая неделя: ${prev.created_issues}, Δ: ${formatDelta(deltaIssues)})
  * Баги (Bugs): ${typeCounts.bug} (было: ${prev.bugs}, Δ: ${formatDelta(deltaBugs)})
  * Задачи (Tasks): ${typeCounts.task} (было: ${prev.tasks}, Δ: ${formatDelta(deltaTasks)})
  * Улучшения (Features): ${typeCounts.feature} (было: ${prev.features}, Δ: ${formatDelta(deltaFeatures)})
  * На триаже (Needs-Triage): ${typeCounts['needs-triage']} (было: ${prev.needs_triage}, Δ: ${formatDelta(deltaTriage)})
- Закрыто Issues: ${totalClosedIssues} (прошлая неделя: ${prev.closed_issues}, Δ: ${formatDelta(deltaClosed)})
- Открыто Pull Requests: ${totalCreatedPRs} (прошлая неделя: ${prev.created_prs}, Δ: ${formatDelta(deltaPRs)})
- Смерджено Pull Requests: ${totalMergedPRs} (прошлая неделя: ${prev.merged_prs}, Δ: ${formatDelta(deltaMerged)})
`;

return [{
  json: {
    startDate: dateInfo.startDate,
    endDate: dateInfo.endDate,
    owner: dateInfo.owner,
    repo: dateInfo.repo,
    promptData: promptData.trim(),
    totalCreatedIssues,
    totalClosedIssues,
    totalCreatedPRs,
    totalMergedPRs,
    typeCounts,
    authorCounts: sortedAuthors,
    prev,
    deltas: {
      issues: formatDelta(deltaIssues),
      closed: formatDelta(deltaClosed),
      prs: formatDelta(deltaPRs),
      merged: formatDelta(deltaMerged),
      bugs: formatDelta(deltaBugs),
      tasks: formatDelta(deltaTasks),
      features: formatDelta(deltaFeatures),
      triage: formatDelta(deltaTriage)
    },
    statsData: {
      week_date: dateInfo.endDate,
      created_issues: totalCreatedIssues,
      closed_issues: totalClosedIssues,
      created_prs: totalCreatedPRs,
      merged_prs: totalMergedPRs,
      bugs: typeCounts.bug,
      tasks: typeCounts.task,
      features: typeCounts.feature,
      needs_triage: typeCounts['needs-triage']
    }
  }
}];

const data = $('Group Stats & Build Delta').first().json;
const llmResult = $input.first().json;
const aiComment = llmResult.text || llmResult.output || llmResult.response || 'На этой неделе зафиксирован рост проектной активности по созданию Pull Requests и новым обращениям. Рекомендуется уделить внимание разбору накопившихся задач и закрытию открытых багов.';

const calcPercent = (val, total) => total > 0 ? Math.round((val / total) * 100) + '%' : '0%';

const deltaBadge = (valStr) => {
  if (valStr.startsWith('+')) {
    return `<span style="font-size: 12px; font-weight: normal; color: #28a745; margin-left: 4px;">(${valStr})</span>`;
  } else if (valStr.startsWith('-')) {
    return `<span style="font-size: 12px; font-weight: normal; color: #cb2431; margin-left: 4px;">(${valStr})</span>`;
  }
  return `<span style="font-size: 12px; font-weight: normal; color: #586069; margin-left: 4px;">(0)</span>`;
};

let authorRowsHtml = '';
if (data.authorCounts.length === 0) {
  authorRowsHtml = '<tr><td colspan="2" style="padding: 10px; text-align: center; color: #6e7781;">За выбранный период созданных Issues нет</td></tr>';
} else {
  for (const [author, count] of data.authorCounts) {
    authorRowsHtml += `<tr><td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8;"><strong>@${author}</strong></td><td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${count}</td></tr>`;
  }
}

const htmlReport = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #24292e; background-color: #f6f8fa; margin: 0; padding: 20px; }
    .container { max-width: 650px; margin: 0 auto; background: #ffffff; border-radius: 8px; border: 1px solid #e1e4e8; overflow: hidden; }
    .header { background: #0366d6; color: #ffffff; padding: 20px 24px; }
    .header h1 { margin: 0 0 6px 0; font-size: 20px; font-weight: 600; }
    .header p { margin: 0; font-size: 13px; opacity: 0.9; }
