    .card:not(:last-child) { border-right: 6px solid #ffffff; }
    .card-val { font-size: 20px; font-weight: 700; color: #0366d6; }
    .card-lbl { font-size: 11px; text-transform: uppercase; color: #586069; margin-top: 4px; font-weight: 600; }
    h2 { font-size: 16px; margin: 20px 0 10px 0; border-bottom: 1px solid #eaecef; padding-bottom: 6px; }
