    th { background: #f6f8fa; padding: 10px 12px; text-align: left; font-weight: 600; color: #24292e; border-bottom: 2px solid #e1e4e8; }
    .badge { display: inline-block; padding: 2px 8px; font-size: 12px; font-weight: 600; border-radius: 12px; }
    .badge-bug { background-color: #ffeef0; color: #d73a49; border: 1px solid #ffdce0; }
    .badge-task { background-color: #f1f8ff; color: #0366d6; border: 1px solid #c8e1ff; }
    .badge-feat { background-color: #f3f0ff; color: #6f42c1; border: 1px solid #e2d9f3; }
    .badge-triage { background-color: #fff8c5; color: #735c0f; border: 1px solid #f9e686; }
    .footer { padding: 16px 24px; background: #f6f8fa; border-top: 1px solid #e1e4e8; font-size: 12px; color: #586069; text-align: center; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>📊 Еженедельный отчёт по Issues</h1>
      <p>Репозиторий: <strong>${data.owner}/${data.repo}</strong> • Период: ${data.startDate} — ${data.endDate}</p>
    </div>
    <div class="content">

      <!-- AI-комментарий недели (Критерий 9) -->
      <div class="ai-box">
        <div class="ai-title">🤖 AI-комментарий недели</div>
        <p class="ai-text">${aiComment}</p>
      </div>

      <!-- Карточки со сводкой и дельтами (Критерий 8) -->
      <div class="cards">
        <div class="card">
          <div class="card-val">${data.totalCreatedIssues} ${deltaBadge(data.deltas.issues)}</div>
          <div class="card-lbl">Новых Issues</div>
        </div>
        <div class="card">
          <div class="card-val" style="color: #28a745;">${data.totalClosedIssues} ${deltaBadge(data.deltas.closed)}</div>
          <div class="card-lbl">Закрыто Issues</div>
        </div>
        <div class="card">
          <div class="card-val" style="color: #6f42c1;">${data.totalCreatedPRs} ${deltaBadge(data.deltas.prs)}</div>
          <div class="card-lbl">Открыто PR</div>
        </div>
        <div class="card">
          <div class="card-val" style="color: #28a745;">${data.totalMergedPRs} ${deltaBadge(data.deltas.merged)}</div>
          <div class="card-lbl">Смерджено PR</div>
        </div>
      </div>

      <h2>📋 Статистика новых Issues по типам (с Δ к прошлой неделе)</h2>
      <table>
        <thead>
          <tr>
            <th>Тип обращения</th>
            <th>Лейбл</th>
            <th style="text-align: right;">Количество</th>
            <th style="text-align: right;">Было (Δ)</th>
            <th style="text-align: right;">Доля</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8;">Баги (Bugs)</td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8;"><span class="badge badge-bug">bug</span></td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;"><strong>${data.typeCounts.bug}</strong></td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${data.prev.bugs} ${deltaBadge(data.deltas.bugs)}</td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${calcPercent(data.typeCounts.bug, data.totalCreatedIssues)}</td>
