            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;"><strong>${data.typeCounts.task}</strong></td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${data.prev.tasks} ${deltaBadge(data.deltas.tasks)}</td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${calcPercent(data.typeCounts.task, data.totalCreatedIssues)}</td>
          </tr>
          <tr>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8;">Улучшения (Features)</td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8;"><span class="badge badge-feat">feature</span></td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;"><strong>${data.typeCounts.feature}</strong></td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${data.prev.features} ${deltaBadge(data.deltas.features)}</td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${calcPercent(data.typeCounts.feature, data.totalCreatedIssues)}</td>
          </tr>
          <tr>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8;">На триаже (Needs Triage)</td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8;"><span class="badge badge-triage">needs-triage</span></td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;"><strong>${data.typeCounts['needs-triage']}</strong></td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${data.prev.needs_triage} ${deltaBadge(data.deltas.triage)}</td>
            <td style="padding: 8px 12px; border-bottom: 1px solid #e1e4e8; text-align: right;">${calcPercent(data.typeCounts['needs-triage'], data.totalCreatedIssues)}</td>
          </tr>
        </tbody>
      </table>

      <h2>👥 Активность авторов</h2>
      <table>
        <thead>
          <tr>
            <th>Пользователь</th>
            <th style="text-align: right;">Создано Issues</th>
          </tr>
        </thead>
        <tbody>
          ${authorRowsHtml}
        </tbody>
      </table>
    </div>
    <div class="footer">
      Автоматический отчёт сгенерирован платформой <strong>n8n</strong> • ITMO AI Engineering Course
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    subject: `📊 [GitHub Weekly Report] Статистика Issues (${data.owner}/${data.repo}) за ${data.startDate}`,
    finalHtmlReport: htmlReport,
    statsData: data.statsData
  }
}];
